html.classList.toggle('ag-dark-mode', this.state.darkMode);
html.classList.toggle('ag-grayscale', this.state.grayscale);
html.classList.toggle('ag-highlight-links', this.state.highlightLinks);
html.classList.toggle('ag-dyslexia', this.state.dyslexiaFont);
html.classList.toggle('ag-pause-motion', this.state.pauseAnimations);
html.classList.toggle('ag-big-cursor', this.state.bigCursor);
html.classList.toggle('ag-focus-ring', this.state.focusRing);
